const QUESTIONS = [
  ['What did you do last weekend?',
    'Last weekend, I spent most of my time at home because I had a busy week. On Saturday morning, I cleaned my room and finished some work. In the evening, I met two friends for coffee. Sunday was quieter, so I watched a film and prepared for the new week.'],
  ['Tell me about the first school you attended.',
    'The first school I attended was a small primary school near my home. I remember the classrooms being bright and the teachers being very friendly. My favorite subject was English because we learned through songs and simple games. I also made several close friends there, so I still have good memories of that school.'],
  ['Describe the room you are in now.',
    'The room I am in now is fairly simple and comfortable. It has a desk, a chair, a bookshelf, and a window that lets in plenty of natural light. I usually keep the space tidy because it helps me concentrate. The room is quiet, so it is a good place for studying and working.'],
  ['Why are you interested in travel?',
    'I am interested in travel because it gives me a chance to see different places and experience new ways of life. I especially enjoy trying local food and visiting natural attractions. Traveling also helps me become more independent because I have to plan routes, manage money, and deal with unexpected situations.'],
  ['What is a popular book in your country that you would recommend?',
    'One popular book I would recommend is a well-known Vietnamese novel about family and everyday life. I like books that show realistic characters and meaningful relationships. A good story can help readers understand another period or perspective. I would recommend this kind of book because it is both enjoyable and culturally interesting.'],
  ['Tell me about your family.',
    'My family is not very large. I live with my parents and one younger sibling, and we usually have dinner together in the evening. Everyone is quite busy during the day, but we try to spend time together at weekends. I value my family because they are supportive and easy to talk to.'],
  ['What do you do for work or study?',
    'At the moment, I spend most of my time studying and working on personal projects. My daily tasks include reading, using a computer, and communicating with other people. I like work that allows me to learn new things and solve problems. In the future, I hope to become more skilled and independent.'],
  ['What is the food like in your country?',
    'Food in Vietnam is very varied, fresh, and full of flavor. Rice and noodles are common, and many dishes include vegetables, herbs, meat, or seafood. I especially like meals that are simple but balanced. Another thing I enjoy is that each region has its own specialties, so there is always something new to try.'],
  ['When do you feel stressed?',
    'I usually feel stressed when I have several important tasks to finish at the same time. Tight deadlines make it difficult to relax because I keep thinking about what I still need to do. When that happens, I make a short plan, finish one task at a time, and take brief breaks to stay focused.'],
  ['Describe one of your favorite places.',
    'One of my favorite places is a quiet park near the center of my city. It has many trees, a walking path, and a small lake. I like going there in the late afternoon because the weather is cooler. It is a good place to exercise, think quietly, or spend time with friends.'],
  ['Tell me about the last time you talked with your mother.',
    'The last time I talked with my mother was earlier today. We spoke about normal family matters, what I was doing, and what we would have for dinner. The conversation was not very long, but I enjoyed it. I try to talk with her regularly because she often gives practical advice and encouragement.'],
  ['What sports are popular in your country?',
    'Football is probably the most popular sport in Vietnam. People enjoy it because the rules are easy to understand and matches can be very exciting. Many people watch major games with friends or family, while others play football themselves. It also creates a strong sense of community when people support the same team.'],
  ['Describe a typical Vietnamese meal.',
    'A typical Vietnamese meal usually includes rice, a main dish of meat or fish, a vegetable dish, and a bowl of soup. Everything is placed in the middle of the table so that people can share. Fresh herbs and dipping sauces are also common. I like this style of eating because it is balanced and social.'],
  ['Describe a typical day in your life.',
    'On a typical day, I get up at about six thirty and have a simple breakfast. Then I spend the morning studying or working on my main tasks. In the afternoon I usually take a short walk to clear my head. In the evening I relax with my family, read something, and go to bed early.'],
  ['What do you like to do in your free time?',
    'In my free time, I enjoy reading, listening to music, and going out with friends. When the weather is nice, I like walking in the park or riding my bicycle. These activities help me relax after a busy day. I also spend some time learning English because it is useful for my future.'],
  ['Tell me about the people in your family.',
    'There are four people in my family: my parents, my younger sibling, and me. My father is calm and practical, while my mother is warm and talkative. My sibling is still studying and is quite energetic. We have different personalities, but we get along well and support each other.'],
  ['Tell me a little about yourself.',
    'My name is Linh and I am in my early twenties. I live in a city in Vietnam with my family. I am currently studying and also improving my English because I want better job opportunities. In my free time, I enjoy reading and meeting friends. I would describe myself as friendly and hard-working.'],
  ['Tell me about your hometown.',
    'My hometown is a medium-sized city with a mix of old and modern buildings. It is quite busy during the day, especially near the markets and schools. What I like most is the food and the friendly people. Although it can be noisy, it feels comfortable and familiar because I grew up there.'],
  ['What is the best way to travel around your country?',
    'I think the best way to travel around my country depends on the distance. For long journeys, planes and trains are the most convenient because they save time. For shorter trips, buses and motorbikes are cheaper and more flexible. Personally, I prefer trains because they are comfortable and you can enjoy the scenery.'],
  ['Tell me about a close friend or family member.',
    'I would like to talk about my closest friend, whom I have known since secondary school. She is cheerful, honest, and always willing to listen. We share similar interests, such as music and travel, so we never run out of things to discuss. I appreciate her because she gives me honest advice.'],
  ['What is your favorite season, and why?',
    'My favorite season is autumn because the weather is cool and comfortable. It is neither too hot nor too cold, so it is pleasant to walk outside. I also like the clear skies and the colors of the leaves. Autumn makes me feel calm and gives me more energy for studying.'],
  ['Tell me about one of your good memories.',
    'One of my good memories is a short trip I took with my classmates after our final exams. We visited a beach, cooked simple food together, and talked until late at night. Nothing special happened, but everyone was relaxed and happy. I remember it clearly because we felt free after months of studying.'],
  ['What do you like doing with your friends?',
    'With my friends, I enjoy having coffee, talking about our daily lives, and sometimes watching films together. We also like trying new restaurants when we have time. Occasionally we take short trips outside the city. I like these activities because they are simple and give us a chance to catch up.'],
  ['What do you like doing in your free time?',
    'In my free time I usually read books, listen to music, or go for a walk. I also enjoy cooking when I have enough time because it helps me relax. At weekends, I prefer meeting friends or visiting my relatives. These activities help me rest and prepare for the following week.'],
  ['Describe a journey you made recently.',
    'Recently I made a short journey to a coastal town about three hours from my city. I travelled by bus with two friends, and the trip was comfortable. We stayed for two days, walked along the beach, and tried local seafood. It was a simple journey, but it helped me relax completely.'],
  ['What are you wearing today?',
    'Today I am wearing quite casual clothes because I am staying at home. I have on a plain cotton shirt, jeans, and comfortable shoes. I usually choose simple clothes in neutral colors because they are easy to combine. When I go to work or to a meeting, I dress more formally.'],
  ['When do you feel tired?',
    'I usually feel tired at the end of a long day, especially if I have been concentrating for many hours. I also feel tired when I do not sleep enough or when I use my computer for too long. To recover, I try to sleep earlier, drink more water, and take short breaks.'],
  ['Describe the room you spend the most time in.',
    'The room I spend the most time in is my bedroom, which I also use for studying. It has a bed, a desk, a small bookshelf, and a large window. I like it because it is quiet and gets plenty of natural light. I try to keep it tidy so that I can concentrate better.'],
  ['What would you look for in a new house or apartment?',
    'If I were looking for a new apartment, I would first consider the location and the price. I would prefer somewhere close to my work with convenient transport. Natural light and a quiet neighborhood are also important to me. Finally, I would check that the building is safe and well maintained.'],
  ['Why are you learning English?',
    'I am learning English mainly because it is important for my career. Many companies require good English for communication and reading documents. English also allows me to access more information online and to travel more confidently. In addition, I enjoy watching films and reading articles in English.'],
  ['What do you often do in your free time?',
    'In my free time I often read, exercise, or meet friends. I also enjoy listening to podcasts because I can learn while doing other things. At weekends I usually spend time with my family or go somewhere new in the city. I try to balance rest and activity so that I feel refreshed.'],
  ['What kind of television content do you usually watch?',
    'I usually watch documentaries and news programs because I like learning about real events. Sometimes I also watch comedy series when I want to relax. I rarely watch television for many hours; I prefer choosing one or two programs. Watching in English also helps me improve my listening skills.'],
  ['What kinds of books do you enjoy reading?',
    'I enjoy reading novels and books about personal development. Novels are interesting because they show different characters and situations. Books about self-improvement are useful because they give practical advice. I usually read for about thirty minutes before bed, as it helps me relax and sleep better.'],
  ['Can you tell me something about your neighborhood?',
    'My neighborhood is quite busy but convenient. There are small shops, a market, and several coffee shops within walking distance. Most of the people living there have been neighbors for a long time, so it feels friendly. The main disadvantage is the traffic noise during rush hour.'],
  ['What do you like most about your neighborhood?',
    'What I like most about my neighborhood is how convenient it is. I can buy food, get a haircut, or find a coffee shop within a few minutes. I also like that the neighbors are friendly and help each other when necessary. It feels safe, which is very important to me.'],
  ['Do you plan to live in your current neighborhood for a long time? Why or why not?',
    'I am not sure if I will stay in my current neighborhood for a long time. I like it because it is convenient and familiar, but it can be noisy and crowded. If I find a job in another area, I would probably move. For now, however, I am happy living here.'],
  ["Let's talk about going out. How often do you go out?",
    'I go out about two or three times a week, usually at weekends. During the week I am often busy with work or study, so I stay at home. When I do go out, I normally meet friends for coffee or dinner. I think this is a reasonable balance for me.'],
  ['Who do you usually go out with?',
    'I usually go out with a small group of close friends I have known for several years. Sometimes I go out with my family, especially for meals or short trips. I prefer going out in small groups because it is easier to talk properly. Occasionally I also go out alone to relax.'],
  ['Where do you often go when you go out?',
    'When I go out, I often go to coffee shops because they are comfortable and good for conversation. I also like visiting parks when the weather is pleasant. Sometimes we go to the cinema or try a new restaurant. I prefer quiet places where we can sit and talk for a while.'],
  ['Now, let’s talk about a special place you would always want to return to. Can you describe that place?',
    'A special place I would always want to return to is a small beach town I visited a few years ago. The beach was clean, the streets were quiet, and the seafood was excellent. I remember watching the sunrise there early in the morning. It is a place where I feel completely relaxed.'],
  ['When you visit a special place, do you usually go alone or with other people?',
    'It depends on the place and my mood. If I want to think quietly or take photographs, I prefer going alone. However, for most trips I like travelling with friends or family because we can share the experience. Having company also makes the journey safer and more enjoyable.'],
  ['What kind of place would you like to visit again, and why?',
    'I would like to visit the mountains in the north of my country again. The scenery is beautiful, the air is fresh, and the local culture is very interesting. On my first visit I only stayed two days, which was not enough. Next time I would like to stay longer and explore more.'],
  ['When and where do you usually go walking?',
    'I usually go walking in the early morning or in the evening when it is cooler. My favorite place is a park near my house because it has trees and a quiet path. Sometimes I also walk around my neighborhood after dinner. Walking helps me relax and think clearly.'],
  ['Do you think walking is important?',
    'Yes, I think walking is very important. It is a simple form of exercise that almost everyone can do, and it does not require special equipment. Walking regularly is good for the heart and helps reduce stress. It also gives me time to think, so I try to walk every day.'],
  ['Do you think walking in the countryside is better than walking in the city?',
    'In some ways, walking in the countryside is better because the air is cleaner and there is less noise and traffic. The scenery is also more relaxing. However, walking in the city is more convenient for daily exercise. Personally, I prefer the countryside at weekends and the city on ordinary days.'],
  ["Let's talk about your eating habits. Do you often eat healthy food?",
    'I try to eat healthy food most of the time. I usually have rice, vegetables, and some meat or fish, and I drink a lot of water. However, I sometimes eat snacks or fast food when I am busy. I think a reasonable balance is more realistic than being extremely strict.'],
  ['What do you usually eat when you are at school or work?',
    'When I am at work, I usually eat a simple lunch such as rice with vegetables and meat. Sometimes I bring food from home because it is cheaper and healthier. If I am very busy, I might buy a sandwich or noodles nearby. I also try to drink water instead of soft drinks.'],
  ['What is the unhealthiest food you can think of?',
    'I think deep-fried fast food is probably the unhealthiest, especially when it is eaten regularly. It usually contains a lot of oil, salt, and sugar but very few nutrients. Sweet drinks are also unhealthy for similar reasons. I do not avoid these foods completely, but I try to eat them rarely.'],
  ["Let's talk about weather. What kind of weather do you like?",
    'I like cool and dry weather the most, which usually happens in autumn. It is comfortable for walking outside and I sleep better at night. I do not enjoy very hot weather because it makes me tired quickly. A little sunshine with a light breeze is ideal for me.'],
  ['Does the weather affect your mood? Why or why not?',
    'Yes, the weather does affect my mood. On sunny days I usually feel more energetic and want to go outside. When it rains for a long time, I feel a little tired and prefer staying at home. I try not to let it affect me too much, but I definitely notice the difference.'],
  ['What do you usually do when the weather is very hot?',
    'When the weather is very hot, I try to stay indoors during the middle of the day. I drink a lot of water, wear light clothes, and use a fan or air conditioning. If I need to go out, I usually go early in the morning or after sunset when it is cooler.'],
  ['What was your favorite game when you were a child?',
    'When I was a child, my favorite game was hide and seek. We played it almost every afternoon in the small alley near my house. I liked it because it was exciting and did not need any equipment. Looking back, I think those simple games made my childhood very happy.'],
  ['Who did you usually play your favorite childhood game with?',
    'I usually played with the children who lived in my neighborhood, and sometimes with my cousins. There were about five or six of us, and we were roughly the same age. We met almost every day after finishing our homework. Because we played together so often, we became very close friends.'],
  ['What skills were useful when you played your favorite childhood game?',
    'I think several skills were useful, especially observation and quick thinking. You had to notice small details and decide where to hide very quickly. Teamwork was also important because we often played in groups. These games also taught us to follow rules and accept losing without getting angry.'],
  ["Let's talk about noise. Do you like to live in a noisy place or a quiet place?",
    'I definitely prefer living in a quiet place. When it is quiet, I can concentrate better and sleep more deeply. My current neighborhood is quite noisy because of traffic, which sometimes makes me tired. However, I do not want somewhere completely silent either, because a little activity feels more lively.'],
  ['What kind of noise disturbs you most?',
    'The noise that disturbs me most is traffic noise, especially motorbike horns early in the morning. It wakes me up and makes it hard to fall asleep again. Construction noise is also very annoying because it continues for hours. I do not mind natural sounds such as rain or birds.'],
  ['Does noise affect your health?',
    'Yes, I believe noise affects health quite seriously. Constant noise makes me feel stressed and gives me headaches after a long day. It also reduces the quality of my sleep, so I feel tired the next morning. Over a long period, I think this could affect concentration and general well-being.'],
  ["Let's talk about your favorite photograph. What is your favorite photograph?",
    'My favorite photograph is a picture of my family taken during a trip to the beach a few years ago. Everyone is smiling and the sunset is in the background. It is not a professional photo, but it captures a genuinely happy moment. I keep it on my desk where I can see it every day.'],
  ['When was your favorite photograph taken, and what was happening at the time?',
    'It was taken about three years ago during a summer holiday. We had just finished dinner at a small restaurant near the beach and decided to walk along the shore. A stranger offered to take the photo for us. Nothing special was happening, but everyone was relaxed and enjoying the evening.'],
  ['What makes the photograph special to you?',
    'What makes it special is not the quality of the picture but the memory behind it. That was one of the few times our whole family travelled together without worrying about work or school. Whenever I look at it, I remember how peaceful that evening was. It reminds me to value time with family.'],
  ['What color do you like most, and why?',
    'My favorite color is blue because it makes me feel calm and comfortable. It reminds me of the sea and the sky, which I find very relaxing. I also think blue is easy to combine with other colors, so most of my clothes are blue or another neutral color.'],
  ['Do you care for colors when choosing clothes to wear?',
    'Yes, I pay attention to colors when choosing clothes, although I am not very fashionable. I usually choose neutral colors such as black, white, or blue because they are easy to match. For formal occasions I prefer darker colors, while in summer I wear lighter ones because they feel cooler.'],
  ['Does color affect your mood? Why or why not?',
    'Yes, I think color does affect my mood to some extent. Bright colors such as yellow or orange make me feel more energetic and cheerful. Darker colors feel more serious and calm. That is why I prefer light colors in my room, because they make the space feel more open and comfortable.'],
  ["Let's talk about going to the library. How often do you go to the library?",
    'I go to the library about once or twice a month, usually at weekends. When I was a student I went much more often because I needed a quiet place to study. Now I mainly go when I want to borrow books or work somewhere without distractions.'],
  ['What do you usually do in the library?',
    'In the library I usually read, study, or borrow books to take home. Sometimes I bring my laptop and work there because the atmosphere helps me concentrate. I also enjoy walking around the shelves to find something interesting. It is a comfortable place to spend a quiet afternoon.'],
  ['Do you think that fewer people go to the library nowadays?',
    'Yes, I think fewer people visit libraries than before because most information is now available online. People can read e-books or search for articles on their phones. However, libraries are still valuable, especially for students who need a quiet study space. Many libraries have also added modern facilities to attract visitors.'],
  ["Let's talk about parties. Do you enjoy going to a party?",
    'I enjoy going to parties, but only small ones with people I know well. Large, crowded parties make me feel a little uncomfortable and it is difficult to have a real conversation. I prefer a relaxed gathering with good food and music where we can talk properly.'],
  ['What do you usually do at a party?',
    'At a party I usually talk with friends, eat, and listen to music. Sometimes I help the host prepare food or drinks because I feel more comfortable when I have something to do. If there are games, I join in. I am not the type of person who dances or sings loudly.'],
  ['On what occasions do you hold a party?',
    'We usually hold parties for birthdays, family anniversaries, and the Lunar New Year. Sometimes we also organize a small gathering when someone graduates or gets a new job. These parties are normally at home rather than at a restaurant, because it is cheaper and feels warmer.'],
  ["Let's talk about your city. Which part of the city do you like best?",
    'The part of the city I like best is the old quarter near the river. It has narrow streets, small coffee shops, and traditional houses. I like walking there in the early morning when it is still quiet. It feels very different from the modern areas with tall buildings.'],
  ['Why do you like your favorite part of your city?',
    'I like it mainly because of the atmosphere. The buildings are old and full of character, and the streets are lively but not too crowded. There are also many small restaurants serving traditional food. It is a place where I can relax, take photographs, and meet friends comfortably.'],
  ['What changes would you like to make to your favorite area of your city?',
    'If I could change something, I would reduce the traffic and create more walking areas. The streets are often crowded with motorbikes, which spoils the atmosphere. I would also add more trees and public seating. I think these changes would make the area more pleasant for both residents and tourists.'],
  ["Let's talk about holidays. What did you do on your last holiday?",
    'On my last holiday I travelled to a coastal city with two friends for three days. We swam in the sea, tried local seafood, and visited a small island nearby. We did not plan a busy schedule, so we had plenty of time to rest. It was a simple but very enjoyable trip.'],
  ['Who do you prefer spending your holidays with?',
    'I prefer spending holidays with close friends or my family. With friends, the trip is usually more flexible and full of activities. With family, it is quieter but more meaningful because we rarely have free time together. Occasionally I travel alone, which is good for thinking and taking photographs.'],
  ['Do you prefer going on holidays abroad?',
    'I would like to travel abroad more often because it is interesting to experience a different culture and language. However, it is expensive and requires more planning. At the moment I usually travel within my country, since there are still many beautiful places I have not visited yet.'],
  ["Now, let's talk about TV programs. How many hours a day do you watch television?",
    'I do not watch much television, probably less than an hour a day. I usually watch the news in the evening while having dinner. At weekends I might watch a film, so the total time is a bit longer. I spend more time watching videos on my phone than on television.'],
  ['What kinds of television programs do you enjoy watching?',
    'I enjoy documentaries about nature, history, and science because I learn something new. I also like cooking programs, since they give me practical ideas. Occasionally I watch comedy series when I want to relax. I rarely watch reality shows because I find them repetitive.'],
  ['Do you prefer watching television alone or with others?',
    'It depends on the program. I prefer watching documentaries alone because I can concentrate fully. However, films and sports are much more enjoyable with family or friends, since we can discuss what is happening. Watching together also makes it a social activity rather than just entertainment.'],
  ['What kind of music do you like best, and why?',
    'I like pop and acoustic music the most because the melodies are pleasant and the lyrics are easy to understand. I usually listen while working or travelling, as it helps me concentrate and feel more relaxed. Sometimes I listen to instrumental music when I need complete focus.'],
  ['What is the most popular kind of music in your country?',
    'Pop music is probably the most popular in Vietnam, especially among young people. Vietnamese pop songs are played everywhere, from coffee shops to shopping centers. Traditional music is still respected but is mostly performed at festivals. Recently, rap has also become very popular with the younger generation.'],
  ['What are some benefits or disadvantages of listening to music?',
    'Listening to music helps reduce stress, improve mood, and make boring tasks more enjoyable. It can also help with concentration when the music has no lyrics. The main disadvantage is that listening with headphones at high volume can damage your hearing. It can also be distracting when you need to study seriously.'],
  ["Now, let's talk about English as a school subject. Did you learn English at secondary school?",
    'Yes, I learned English at secondary school for several years. The lessons focused mainly on grammar and vocabulary, with a lot of written exercises. We had few opportunities to practise speaking, so my confidence was quite low. However, it gave me a useful foundation that I am building on now.'],
  ['What do you think about how English is taught at school now?',
    'I think English teaching has improved because there is more focus on communication rather than only grammar. Many schools now use videos, group activities, and native teachers. However, classes are still quite large, so students do not get enough speaking practice. There is definitely room for further improvement.'],
  ['How has English learning for children improved in recent years?',
    'Children now start learning English much earlier, often in primary school or even kindergarten. There are also many applications, cartoons, and songs that make learning enjoyable. Teaching methods focus more on listening and speaking than before. As a result, many children today are far more confident than my generation was.'],
  ['Describe a beautiful place in your hometown.',
    'A beautiful place in my hometown is a lake near the city center. It is surrounded by old trees and has a path where people walk or jog. In the early morning it is peaceful and the water is very calm. Many families come there in the evening to relax together.'],
  ['What is the best way to travel to a beautiful place in your hometown?',
    'The best way is probably by motorbike, because it is fast and you can park easily. If the weather is pleasant, walking or cycling is even better because you can enjoy the scenery. Buses also run nearby, but they are less convenient since they do not stop very close.'],
  ['What is the best time to visit a beautiful place in your hometown?',
    'I think early morning is the best time because the air is fresh and there are fewer people. Late afternoon is also lovely, especially around sunset when the light is beautiful. I would avoid the middle of the day in summer because it becomes extremely hot.'],
  ['Have you ever visited a traditional village? Tell me about the experience.',
    'Yes, I visited a traditional pottery village about two years ago. I watched craftsmen shaping clay by hand and even tried making a small bowl myself. The houses and narrow lanes looked much the same as they did decades ago. It was a relaxing day and I learned a lot about the craft.'],
  ['What is your favorite traditional village in your country?',
    'My favorite is a craft village near Hanoi that is famous for its pottery. I like it because the atmosphere is peaceful and the local people are friendly. You can watch the whole production process and buy products directly from the workshops. It feels much more authentic than a normal tourist attraction.'],
  ['What can people do to preserve traditional villages?',
    'I think the most important thing is to help young people earn a living from traditional crafts, otherwise they will move to the cities. The government could support training and promote these products more widely. Responsible tourism also helps, as long as it does not change the character of the village.'],
  ['What is your favorite room in your home?',
    'My favorite room is my bedroom because it is quiet and completely my own space. It has a comfortable bed, a desk by the window, and a small bookshelf. I spend most of my time there reading or studying. I like it because I can control how tidy and quiet it is.'],
  ['What do you usually do in your favorite room at home?',
    'In my bedroom I mainly study, read, and listen to music. I also use it for video calls with friends because it is quiet. Before sleeping, I usually read for about half an hour. Occasionally I rearrange the furniture, which makes the room feel new again.'],
  ['What would you like to change about your favorite room at home?',
    'I would like to make the room a little larger and add more storage space. At the moment my books and belongings take up too much of the floor. I would also buy a better desk lamp, since the current lighting is not very good for reading at night.'],
  ['Do you live in a house or an apartment?',
    'I live in a house with my family. It has three bedrooms, a living room, and a small yard where my mother grows vegetables. I like living in a house because it is more spacious than an apartment. However, an apartment would probably be easier to clean and maintain.'],
  ['Who do you live with?',
    'I live with my parents and my younger sibling. My grandparents live nearby, so they visit us regularly. Living together means the house is rarely quiet, but I enjoy having company. We usually have dinner together, which is the time when we talk about our day.'],
  ['Which room does your family spend most of the time in?',
    'My family spends most of the time in the living room. It is where we watch television, receive guests, and talk after dinner. It is the largest room and has the most comfortable seating. The kitchen is also busy, especially in the evening when we prepare meals together.'],
  ['How often do you go to a library, and why do you go there?',
    'I go to a library roughly twice a month. I mainly go there to borrow books and to study in a quiet environment. Sometimes I also go simply to relax and read magazines. The library is free and comfortable, which makes it a convenient place to spend time.'],
  ['What activities do people often do in the library?',
    'Most people go to the library to read, study, or borrow books. Students often work in groups on projects, while others use the free internet. Some libraries also organize events such as book talks or workshops for children. It has become more than just a place for reading.'],
  ['How would you recommend a book to another person?',
    'First I would ask what kind of books that person usually enjoys, so my suggestion is suitable. Then I would explain briefly what the book is about without revealing the ending. I would also mention why I personally liked it. If possible, I would lend them my copy.'],
  ['Have you ever had a job, school, or university interview?',
    'Yes, I have had a few interviews, including one for a part-time job and one for a university programme. The first interview made me quite nervous because I had no experience. After preparing more carefully, the later ones went much better. Each interview taught me something useful.'],
  ['What do you usually prepare before a job or school interview?',
    'Before an interview I research the company or school carefully so I understand what they want. I prepare answers for common questions and practise them aloud. I also choose suitable clothes and check the location in advance. Good preparation helps me feel much more confident.'],
  ['How did you feel during your most recent interview?',
    'I felt nervous at the beginning, especially during the first few questions. However, the interviewer was friendly and asked clear questions, so I gradually relaxed. By the end I felt reasonably confident about my answers. Afterwards I realised that preparation had made a real difference.'],
  ['Have you ever used banking services in your local area?',
    'Yes, I have used banking services near my home several times. There is a branch about ten minutes away, and there are also ATMs nearby. I mainly go there to withdraw cash or transfer money. The staff are usually polite, although the branch can be crowded at the end of the month.'],
  ['How often do you use banking services?',
    'I use banking services almost every day, but usually through a mobile application. I transfer money, pay bills, and check my balance on my phone. I only visit a branch two or three times a year for something complicated. Online banking has made everything much faster and more convenient.'],
  ['What do you like about banking services?',
    'What I like most is the convenience of online banking. I can make a transfer at any time without leaving my house, and the transaction is completed within seconds. I also appreciate the security features, such as verification codes. The main disadvantage is that customer service can be slow when there is a problem.'],
  ['Do you ever use a dictionary when learning English?',
    'Yes, I use a dictionary very often when I am learning English. Whenever I meet an unfamiliar word while reading, I look it up immediately. I usually use an online dictionary because it also gives pronunciation and example sentences. I find that seeing a word in context helps me remember it better.'],
  ['What do you usually use a dictionary for?',
    'I mainly use a dictionary to check the meaning and pronunciation of new words. I also look at example sentences to understand how a word is actually used. Sometimes I check whether a word is formal or informal. Occasionally I use it to find synonyms when I am writing.'],
  ['Do you prefer paper or electronic dictionaries?',
    'I definitely prefer electronic dictionaries because they are faster and more convenient. I can search for a word in a few seconds and listen to the pronunciation. They are also free and always available on my phone. Paper dictionaries are useful for studying deeply, but I rarely use them now.'],
  ['Do you use body language when communicating with other people?',
    'Yes, I use body language quite naturally when I speak. I often use hand gestures to explain something, and I try to make eye contact so the other person knows I am listening. I think facial expressions are especially important. Sometimes body language communicates more clearly than words.'],
  ['In what situations do you use body language most?',
    'I use body language most when I am speaking a foreign language and cannot find the right word. Gestures help me express my meaning. I also rely on it in noisy places where speaking is difficult. In presentations, I use gestures to emphasise important points and keep the audience interested.'],
  ['What are the benefits of body language?',
    'Body language helps people understand each other more easily, especially when there is a language barrier. It also shows emotions and attitudes that words alone cannot express. In conversations, it signals that you are listening and interested. However, gestures can mean different things in different cultures, so we should be careful.'],
  ['What foreign languages can you speak or study?',
    'At the moment I am studying English, which is the only foreign language I can use with some confidence. I studied a little Chinese at school, but I have forgotten most of it. I would like to learn another language in the future, perhaps Japanese or Korean, because they interest me.'],
  ['Do you enjoy learning a foreign language?',
    'Yes, I generally enjoy it, especially when I can understand a film or conversation without subtitles. That feeling of progress is very motivating. The difficult part is speaking, because I worry about making mistakes. Overall, I find learning languages rewarding because it opens up new opportunities.'],
  ['How important is it to learn a foreign language?',
    'I think it is very important nowadays. Knowing a foreign language, especially English, gives you access to more information and better job opportunities. It also makes travelling much easier and more enjoyable. Beyond practical benefits, learning a language helps you understand another culture and way of thinking.'],
  ['Can you tell me about your job?',
    'At the moment I am mainly studying, but I also do some part-time work related to office administration. My tasks include organising documents, replying to emails, and helping with simple reports. I enjoy it because the schedule is flexible. In the future I hope to find a full-time job in a similar field.'],
  ['Do you have a part-time job?',
    'Yes, I have a part-time job that I do a few afternoons each week. It is not very demanding, so I can still focus on my studies. The pay is modest, but it covers some of my personal expenses. More importantly, it gives me useful experience of a real working environment.'],
  ['What are the benefits of having a part-time job?',
    'A part-time job helps you earn your own money and become more independent. It also teaches practical skills such as time management and communication with colleagues. Having some work experience is valuable when you apply for a full-time job later. The main risk is that it can affect your studies if you work too much.'],
  ['How often do you watch TV?',
    'I do not watch television very often, perhaps three or four times a week. I usually watch the evening news while having dinner with my family. At weekends I sometimes watch a film. Most of my viewing is actually on my phone or laptop rather than on a television.'],
  ['What is your favourite TV program?',
    'My favourite programs are documentaries about nature and travel. I enjoy seeing places I have never visited and learning how people live in other countries. The photography in these programs is usually beautiful. I also like that I can learn something useful while relaxing at the same time.'],
  ['What are the advantages of watching TV?',
    'Television is a good source of news and information, and it can be very educational. Documentaries and language programs help people learn without much effort. It is also a way for families to relax together in the evening. The disadvantage is that watching too much can waste time and reduce physical activity.'],
  ['Do you often eat healthy food?',
    'I try to eat healthy food most days. My meals usually contain rice, vegetables, and some meat or fish, and I drink plenty of water. However, when I am busy I sometimes eat fast food or instant noodles. I think eating reasonably well most of the time is more realistic than being perfect.'],
  ['What do you usually eat at school or at work?',
    'At work I usually have a simple lunch such as rice with vegetables and meat. Sometimes I bring food from home because it is cheaper and healthier than eating out. If I am in a hurry, I buy a sandwich or a bowl of noodles nearby. I try to avoid sugary drinks.'],
  // "What is the unhealthiest food you can think of?" đã có ở trên (câu 48),
  // nguồn lặp lại nên bỏ bản này.
  ['What game did you enjoy playing most when you were a child?',
    'The game I enjoyed most as a child was hide and seek. We played it in the alley near my house almost every evening. It required no equipment, only friends and some free time. I liked the excitement of trying not to be found, and we always laughed a lot.'],
  ['Who did you most often play childhood games with?',
    'I mostly played with the children living in my neighbourhood, and sometimes with my cousins during the holidays. There were usually five or six of us, all about the same age. We met after finishing our homework. Playing together every day made us very close friends.'],
  ['What abilities helped you play childhood games well?',
    'Being quick and observant helped a lot, especially in games like hide and seek or tag. You needed to notice small details and react fast. Teamwork was also important because many games were played in groups. Those games quietly taught us to cooperate and to accept losing calmly.'],
  ['What color do you like most?',
    'My favourite colour is blue because it makes me feel calm and comfortable. It reminds me of the sea and the sky, which I find very relaxing. Blue is also easy to combine with other colours, so many of my clothes and belongings are blue.'],
  ['How important is color when you choose clothes?',
    'Colour is fairly important to me, although I am not very fashionable. I usually choose neutral colours such as black, white, or navy because they match easily. For formal occasions I prefer darker colours, while in summer I wear lighter ones because they feel cooler and more comfortable.'],
  // "Does color affect your mood? Why or why not?" đã có ở trên (câu 63),
  // nguồn lặp lại nên bỏ bản này.
  ['How do you usually celebrate your birthday?',
    'I usually celebrate my birthday quietly with my family. We have a special meal at home, and my mother often makes a cake. Sometimes I also meet a few close friends for coffee. I have never liked big parties, so a simple celebration suits me much better.'],
  ['What is the best birthday gift you have received?',
    'The best birthday gift I have received was a wristwatch from my parents when I finished secondary school. It was not expensive, but they chose it carefully and I still wear it. What made it special was the meaning behind it rather than the price.'],
  ['What are your plans for your next birthday?',
    'For my next birthday I would like to do something a little different, perhaps a short trip with two or three close friends. I would prefer somewhere quiet near the sea or in the mountains. If that is not possible, I will simply have dinner with my family as usual.'],
  ['What type of mobile phone do you use?',
    'I use a fairly ordinary smartphone that I bought about two years ago. It is not the newest model, but it still works well for everything I need. It has a good camera and enough storage for my photos. I usually keep a phone for several years before replacing it.'],
  ['What do you use your mobile phone for?',
    'I use my phone mainly for messaging, calls, and checking email. I also use it for online banking, listening to music, and reading news. It is very useful for learning English because I have dictionary and study applications. I take photographs with it as well.'],
  ['Do you think you should change anything in the way that you use your mobile phone?',
    'Yes, I think I should reduce the time I spend on social media. I often check my phone without any real reason, which wastes time and affects my concentration. I have started leaving my phone in another room while studying, and that has already helped a lot.'],
  ['What foreign languages are you currently studying?',
    'At the moment I am focusing only on English because I want to improve enough for work. I study almost every day, mainly listening and speaking. In the past I learned a little Chinese, but I have not continued. Once my English is stronger, I may start another language.'],
  ['Do you think that English is the most important language?',
    'English is certainly the most widely used language for international communication, business, and academic research, so it is very important. However, I would not say it is the most important in every situation. Other languages such as Chinese and Spanish are also valuable, depending on where you live and work.'],
  ['What do you find difficult about studying languages?',
    'The most difficult part for me is speaking fluently, because I often worry about grammar mistakes and hesitate. Listening to fast natural speech is also challenging. Vocabulary is easier, but it is hard to remember words if I do not use them regularly. Consistent daily practice is the only solution.'],
  ["Let's talk about public transportation. What is the best way to travel in your town or city?",
    'In my city, the most convenient way to travel is by motorbike because it is fast and easy to park. Buses are cheaper and more comfortable, but the routes are limited and they can be slow during rush hour. For short distances I often prefer walking or cycling.'],
  ['What is your favourite means of transportation?',
    'For long journeys my favourite is the train, because it is comfortable and I can enjoy the scenery. For daily travel, I prefer a motorbike since it is quick and flexible. I also like walking when the distance is short and the weather is pleasant.'],
  ['Do you think people should use public transportation more?',
    'Yes, I think so. If more people used buses or trains, there would be less traffic and less air pollution in the city. It is also cheaper than owning a private vehicle. However, public transport must first become more reliable and cover more areas, otherwise people will not change their habits.'],
  ["Let's talk about your holidays. Where would you like to go for your next holiday?",
    'For my next holiday I would like to visit the mountains in the north of my country. I have seen many photographs of the terraced fields and they look beautiful. I would like to stay for about four days, walk in the countryside, and try the local food.'],
  ['What do people in your country do during their holidays?',
    'During public holidays most people in my country travel back to their hometown to visit family. Others go to the beach or to mountain areas, so tourist places become very crowded. Some people simply stay at home and rest. Family gatherings and shared meals are the most common activity.'],
  ['Why are holidays important?',
    'Holidays are important because they give people a chance to rest and recover from work or study. Without breaks, people become tired and less productive. Holidays are also valuable for spending time with family, which is difficult during busy working weeks. They help maintain both physical and mental health.'],
  ["Let's talk about childhood. Did you enjoy your childhood?",
    'Yes, I enjoyed my childhood very much. I grew up in a quiet neighbourhood where many children of the same age lived, so I always had someone to play with. Life was simple and I had few worries. Looking back, I feel grateful for those carefree years.'],
  ['What do you find most memorable about your childhood?',
    'What I remember most clearly is playing outside with my friends every afternoon until it got dark. We invented our own games and never felt bored. I also remember family meals during the Lunar New Year. Those memories are simple, but they still make me happy.'],
  ['Did you have a lot of friends when you were small?',
    'Yes, I had quite a lot of friends because many children lived in my neighbourhood. We went to the same primary school and played together every day. I was not particularly outgoing, but it was easy to make friends at that age. I still keep in touch with two of them.'],
  ["Let's talk about sports. Do you do any sports or exercise at the moment?",
    'Yes, I exercise regularly although not very intensively. I walk for about thirty minutes most evenings and sometimes ride my bicycle at weekends. I used to play badminton with friends, but recently I have been too busy. I try to stay active because it helps me sleep better.'],
  ["What's your favourite sport?",
    'My favourite sport is badminton because it is easy to play and does not require expensive equipment. I enjoy it most when playing with friends rather than competitively. I also enjoy watching football on television, especially important matches, although I rarely play it myself.'],
  ['Do your family members play any sports?',
    'My father goes walking every morning and occasionally plays badminton with his colleagues. My younger sibling plays football at school and is much more active than I am. My mother prefers gentle exercise such as yoga at home. So most of my family are reasonably active in different ways.'],
  ['What was your favorite childhood game?',
    'My favourite childhood game was hide and seek. We played it almost every day in the small streets near my house. It needed nothing except a few friends, which is why we could play so often. I loved the excitement of hiding and waiting to be found.'],
  ['Who usually joined you when you played your favorite childhood game?',
    'My neighbours and classmates usually joined me, and my cousins came during the school holidays. We were normally a group of about six children of a similar age. Because we met almost every day, we understood each other well and rarely argued about the rules.'],
  ['Why was your favorite childhood game enjoyable for you?',
    'It was enjoyable because it was exciting and unpredictable, and every round felt different. There was also a strong social element, since we played in a group and laughed a lot. It cost nothing and required no equipment, so we could play whenever we had free time.'],
  ['Describe your room.',
    'My room is quite small but comfortable. There is a bed near the window, a wooden desk where I study, and a bookshelf beside it. The walls are painted a light colour, which makes the space feel larger. I keep it tidy because I find it easier to concentrate in a clean room.'],
  ['What are your plans for tonight?',
    'Tonight I plan to have dinner with my family and then finish some work I started this afternoon. After that I will probably read for a while or watch an episode of a series. I want to go to bed reasonably early because I have a busy day tomorrow.'],
  ['What is your favourite film?',
    'My favourite film is an animated film I first watched as a child and have seen many times since. The story is simple but touching, and the music is beautiful. I like it because it always puts me in a good mood. Every time I watch it, I notice small details I missed before.'],
  ['Who is your favourite singer?',
    'My favourite singer is a Vietnamese artist whose songs are gentle and easy to listen to. I like her voice because it sounds warm and natural rather than overproduced. Her lyrics are usually about everyday life and relationships. I often listen to her music when I want to relax after work.'],
  ['Tell me about a book you have read.',
    'I recently read a novel about a family living through a difficult period of history. The story follows three generations, so you see how their lives gradually change. What I liked most was the realistic characters. It was not a quick read, but it made me think about my own family.'],
  ['Tell me about a film you have watched.',
    'Last month I watched a documentary about ocean life. It showed creatures I had never seen before and explained how climate change is affecting them. The photography was stunning and the narration was easy to follow. I found it both entertaining and educational, so I recommended it to my friends.'],
  ['What book have you read recently?',
    'The book I read most recently was about building better daily habits. It explained why small changes are more effective than dramatic ones. I liked it because the advice was practical and each chapter was short. Since reading it, I have started a few simple routines that are working well.'],
  ['What film have you watched recently?',
    'The last film I watched was a comedy that a friend recommended. The plot was not particularly original, but the acting was funny and the pace was quick. I watched it at home on a rainy evening. It was not a great film, but it was exactly what I needed to relax.'],
  ['Who is your favourite actor?',
    'My favourite actor is someone who usually plays ordinary people rather than heroes. I admire him because his performances feel natural and believable. He has appeared in both serious dramas and light comedies, which shows his range. Whenever I see his name, I am confident the film will be worth watching.'],
  ['What was the first foreign language you learned?',
    'The first foreign language I learned was English. I started when I was about eight years old, mostly through songs and simple picture books. At that age I did not understand much grammar, but I enjoyed the sounds of the language. It has remained the only language I use regularly.'],
  ['When and where did you start learning your first foreign language?',
    'I started learning English at primary school when I was around eight. The lessons were twice a week and focused mainly on vocabulary and songs. Later, my parents also sent me to a small evening class near our house. That was where I first practised speaking with other children.'],
  ['What helped you most when learning your first foreign language?',
    'What helped me most was watching films and listening to songs in English. It made the language feel natural rather than like a school subject. Having a patient teacher who encouraged us to speak was also important. More recently, using mobile applications every day has helped me build vocabulary steadily.'],
  ['What do you usually do in the afternoon or evening?',
    'In the afternoon I usually continue working or studying, and I take a short walk to stay alert. In the evening I have dinner with my family and then relax. I often read, listen to music, or review some English. I try to stop using my phone before going to bed.'],
  ['What sport is popular in Vietnam, and why do people enjoy it?',
    'Football is by far the most popular sport in Vietnam. People enjoy it because the rules are simple and you only need a ball to play. Major matches bring the whole country together, and streets are full of supporters afterwards. It creates a strong sense of community and national pride.'],
  ['When was the last time you met friends at a cafe?',
    'The last time was about a week ago, when I met two friends at a small coffee shop near my house. We talked for around two hours about work and recent news. The place was quiet, which made conversation easy. We try to meet like this once or twice a month.'],
  ['Tell me about a book you bought recently.',
    'I bought a book about photography a few weeks ago. I chose it because I want to improve the pictures I take when travelling. It explains composition and lighting with many clear examples. It was not cheap, but I think it was worth the money since I use it regularly.'],
  ['Do you prefer buying books online or in a bookshop? Why?',
    'I usually buy books online because it is cheaper and the choice is much wider. However, I still enjoy visiting bookshops occasionally. In a shop you can look through a book before deciding, and you sometimes discover something unexpected. So I use both, depending on whether I already know what I want.'],
];

function buildDoc(index, question, sample) {
  const id = 'a7000000-0000-4000-8000-' + String(index + 1).padStart(12, '0');
  return {
    _id: id,
    questionSetId: id,
    revision: NumberInt(1),
    schemaVersion: NumberInt(1),
    partId: PART_ID,
    taskTypeCode: TASK_TYPE,
    title: question,
    instructions: 'Trả lời câu hỏi. Ghi âm tối đa 30 giây.',
    accessLevel: 'FREE',
    stimulus: null,
    sections: [],
    items: [{
      // itemId trùng nhau giữa các bộ là bình thường: khi gộp, snapshot factory
      // tự thêm tiền tố questionSetId nên câu trả lời không đè lên nhau.
      id: 'item_1',
      sequenceNo: NumberInt(1),
      prompt: { format: 'PLAIN_TEXT', value: question },
      responseType: 'AUDIO_RECORDING',
      required: true,
      maxScore: ITEM_SCORE,
      options: [],
      leftItems: [],
      rightItems: [],
      // responseSeconds là khoá RecordingRenderer đọc; đặt sai tên thì giao diện
      // rơi về mặc định 60 giây.
      constraints: { responseSeconds: 30 },
      rubricCode: 'APTIS_SPEAKING',
      answerKey: null,
      // Đây là CÂU TRẢ LỜI MẪU học viên xem tham khảo
      explanation: { format: 'PLAIN_TEXT', value: sample },
    }],
    assets: [],
    settings: {
      shuffleOptions: false,
      shuffleItems: false,
      maxAudioPlays: null,
      showAnswerAfterEachItem: false,
      allowReview: true,
    },
    scoring: { strategy: 'RUBRIC', partialCredit: true, maxScore: ITEM_SCORE },
    createdAt: new Date(),
    updatedAt: new Date(),
  };
}

let count = 0;
QUESTIONS.forEach(function (entry, index) {
  const doc = buildDoc(index, entry[0], entry[1]);
  target.question_set_documents.replaceOne({ _id: doc._id }, doc, { upsert: true });
  count++;
  print('  ' + String(index + 1).padStart(2, ' ') + '. ' + entry[0]);
});

print('---');
print('Đã ghi ' + count + ' câu Speaking Part 1.');
print('Tổng document Part 1 = ' + target.question_set_documents.countDocuments({ partId: PART_ID }));
